import { LANG } from './i18n'

// The words for scanner/deep.py. The server sends a code and parameters; {name} is filled in here.
// [title, what was found, how to fix]. tests/test_deep.py checks every code the server can send is here.
export type Entry = [string, string, string?]
export type ChainWords = { title: string; fact: string; could: string; fix: string }
type Words = {
  items: Record<string, Entry>
  chains: Record<string, ChainWords>
  ui: {
    tab: string; about: string; start: string; running: string; passive: string
    modules: Record<'surface' | 'mail' | 'tech' | 'tls' | 'reputation' | 'active' | 'crawl' | 'probe', string>
    retry: string; failed: string; chainsTitle: string; chainsLead: string; chainsNone: string; chainsWait: string
    levels: Record<'critical' | 'high' | 'medium', string>
    fact: string; could: string; fix: string
    hosts: string; software: string; none: string; nameservers: string; records: string; lists: string
    flags: Record<'takeover' | 'dangling' | 'dead' | 'sensitive' | 'private', string>; offline: string
    safeBrowsing: string; since: (date: string) => string; newHosts: string; newProblems: string; solved: string; noChange: string
    ownTitle: string; ownLead: string; ownOnly: string; ownStart: string; ownDns: string; ownDnsHint: string; ownFile: string; ownFileHint: string; ownCode: string
    ownCheck: string; ownChecking: string; ownNotYet: string; limits: string
  }
  pdf: PdfWords
}

export type PdfWords = {
  download: string; busy: string; view: string; error: string; fileName: string
  title: string; site: string; date: string; confidential: string
  verdictTitle: string; verdicts: Record<'critical' | 'high' | 'medium' | 'none', string>; incomplete: string
  scope: string; states: Record<'done' | 'partial' | 'failed' | 'notRun', string>
  contents: string; plan: string; planLead: string; planEmpty: string; scenarios: string; scenariosLead: string
  intro: Record<'surface' | 'mail' | 'tech' | 'tls' | 'reputation' | 'active' | 'crawl' | 'probe', string>
  activeNotRun: string; partFailed: string; hostName: string; pointsTo: string; state: string; working: string
  yes: string; no: string; issuer: string; apex: string; filesChecked: string; portsChecked: string
  method: string; sourcesTitle: string; sources: string[]; limitsTitle: string; limits: string[]
  glossary: string; terms: [string, string][]
  x: Record<string, string>
  fixes: Record<string, [string, string]>
  tags: Record<string, string>
  headerDesc: Record<string, string>
}

