  chains: {
    brand_phish: { title: 'Convincing fraud in your name', fact: '{host} could be taken over, and mail in your name is not stopped.', could: 'An attacker could open a fake login page on that subdomain and send it to your customers by mail from your address. Both the address and the mail would look genuine.', fix: 'Delete the CNAME first (a few minutes of work), then move DMARC step by step to p=reject.' },
    exposed_secret: { title: 'A private file is open to everyone', fact: '{path} opens from the internet.', could: 'Such files often hold database passwords or keys. Whoever reads them could reach the site’s data.', fix: 'Delete the file today and change every password and key in it: it may already have been seen.' },
    open_database: { title: 'A service is directly open to the internet', fact: 'Port {port} ({service}) accepts connections from outside.', could: 'Such services get password guessing and searches for old weaknesses. If set up without a password, the data can be read directly.', fix: 'Close the port with a firewall and allow only the addresses that need it.' },
    subdomain_takeover: { title: 'Your subdomain could pass to someone else', fact: '{host} points to a service that no longer works ({target}).', could: 'Whoever claims that name at the service could show any page on your domain, for example a fake login form.', fix: 'Delete the CNAME from DNS.' },
    fake_mail: { title: 'Fake mail in your name', fact: 'Your DNS records do not stop fake mail.', could: 'Someone could send your customer or employee a message like "our payment card changed" from your address, and it may arrive.', fix: 'Move DMARC step by step to p=reject. The SPF and DMARC generators are in Tools.' },
    script_injection: { title: 'An old library and no safety net', fact: '{name} {version} has known weaknesses and the site has no CSP header.', could: 'If the weakness triggers in your code, a foreign script could run in a visitor’s browser. Without CSP no extra layer stops it.', fix: 'Update the library and add the header with the CSP generator in Tools.' },
    old_runtime: { title: 'A site running on software that gets no updates', fact: 'Security support for {name} {version} ended on {date}.', could: 'Weaknesses found from now on are not fixed in this version, so the risk grows with time.', fix: 'Plan the move to a supported version.' },
    forgotten_service: { title: 'Services that may be forgotten', fact: 'These names work: {hosts}.', could: 'Test and old services usually go without updates and keep weak passwords. Attackers look at them before the main site.', fix: 'Go through the list and switch off what is not needed.' },
    weak_transport: { title: 'Traffic could be pushed to old encryption', fact: 'The server accepts old TLS and has no HSTS header.', could: 'An attacker on the same network (public Wi-Fi, say) could, in the right conditions, try to pull the connection down. This is hard in practice but easy to prevent.', fix: 'Turn off TLS 1.0 and 1.1 and add the HSTS header.' },
    domain_loss: { title: 'The domain is expiring', fact: '{days} days are left on the domain ({date}).', could: 'Without renewal the site and mail stop. Someone else could buy the freed domain and read mail sent to you.', fix: 'Renew now and turn on auto-renewal.' },
    dangling_record: { title: 'A DNS record points to nothing', fact: '{host} points to {target}, which does not exist.', could: 'If someone acquires that name, their content opens on your subdomain.', fix: 'Delete the record if it is not needed.' },
    bad_reputation: { title: 'Your address is on a blocklist', fact: '{target}: {list}.', could: 'Your mail may land in spam or be refused. This can also be a sign that the site was hacked.', fix: 'Find the reason on the list’s site and check the site for harmful code.' },
    leaked_key: { title: 'A secret key is in public code', fact: 'Text that looks like a {kind} key is in {path}.', could: 'Whoever reads the file could act in your account’s name: read data, spend money, send mail.', fix: 'Revoke the key today, create a new one and keep it only on the server.' },
    password_exposed: { title: 'Passwords can be read on the way', fact: 'A password form sends data unencrypted.', could: 'Someone on the same network, such as public Wi-Fi, could see the passwords of people logging in.', fix: 'Move the whole site to HTTPS.' },
    browser_warning: { title: 'Visitors may see a danger warning', fact: 'Google Safe Browsing has flagged this site: {threats}.', could: 'Browsers may show a red warning before opening the site. This can also be a sign that the site was hacked.', fix: 'Clean the site, then ask for a review in Search Console.' },
    plugin_risk: { title: 'A plugin may be the site’s weak point', fact: 'A risk was found for the {slug} plugin.', could: 'Many attacks on WordPress sites come through old plugins. If the weakness triggers, control of the site could be taken.', fix: 'Update or delete the plugin, and delete those you do not use.' },
    open_folder: { title: 'Your files show as a list', fact: 'The folder {path} is open to everyone.', could: 'Uploaded documents and forgotten backups could be found.', fix: 'Turn off directory listing and remove sensitive files from it.' },
    data_read: { title: 'Another site could read a visitor’s data', fact: 'The site allows logged-in requests from any address.', could: 'If a visitor logged in to you opens a harmful site, that site could read their data.', fix: 'Keep only trusted addresses in the CORS rule.' },
    zone_open: { title: 'Your whole DNS map is open', fact: '{server} gives the DNS zone to anyone who asks.', could: 'An attacker could learn the names of all internal services with one request.', fix: 'Close zone transfer.' },
    outside_code: { title: 'Outside code runs on your site', fact: 'Unsigned scripts load from these addresses: {hosts}, and there is no CSP.', could: 'If one of those services is hacked, code stealing your visitors’ data could run on your site.', fix: 'Remove unneeded scripts and add integrity and CSP to the rest.' },
    sql_injection: { title: 'Tampering with the database query', fact: 'The {path} ({param}) parameter may reach the database query.', could: 'If confirmed, an attacker could read or delete customer data and passwords. It is about the most serious risk a site can have.', fix: 'Move to parameterised queries (prepared statements). Check this urgently.' },
    xss: { title: 'Foreign script in a visitor’s browser', fact: 'Input to {path} ({param}) returns to the page without cleaning.', could: 'An attacker could send a visitor a link that runs script in their browser and steals their session.', fix: 'Escape output and add CSP.' },
    csrf: { title: 'Forms may be open to forged requests', fact: 'Password forms show no CSRF token.', could: 'An attacker could make a user perform an action without their knowledge.', fix: 'Add a CSRF token to every form.' },
    server_cves: { title: 'Known weaknesses for the server software', fact: '{name} {version} has {count} CVE entries.', could: 'Since the version is visible to all, an attacker easily finds a matching weakness. If your host has patched it, there is no risk.', fix: 'Ask your host, hide the version and update.' },
  },
